using RedKey.Domain.Common;
using RedKey.Domain.Enums;

namespace RedKey.Domain.Entities.Accounting;

/// <summary>A double-entry journal entry: its lines always balance (total debit = total credit). Never deleted — reversed.</summary>
public class JournalEntry : BaseEntity
{
    private readonly List<JournalLine> _lines = [];

    private JournalEntry() { }

    /// <summary>JE-100001…, generated by the database sequence.</summary>
    public string Number { get; private set; } = null!; // null → the database default (sequence) fills it

    public DateTime EntryDateUtc { get; private set; }
    public string DescriptionAr { get; private set; } = string.Empty;
    public string DescriptionEn { get; private set; } = string.Empty;
    public JournalSourceType SourceType { get; private set; }
    /// <summary>The record behind it (viewing request, sale...).</summary>
    public Guid SourceId { get; private set; }
    /// <summary>The unit it belongs to (the unit "entries" button).</summary>
    public Guid? UnitId { get; private set; }
    /// <summary>Set on a reversing entry: the entry it cancels.</summary>
    public Guid? ReversalOfId { get; private set; }
    /// <summary>Set on an original entry once a reversing entry cancelled it.</summary>
    public bool IsReversed { get; private set; }
    public Guid CreatedByUserId { get; private set; }

    public IReadOnlyCollection<JournalLine> Lines => _lines;

    public static JournalEntry Create(
        JournalSourceType sourceType,
        Guid sourceId,
        Guid? unitId,
        string descriptionAr,
        string descriptionEn,
        Guid createdByUserId,
        DateTime nowUtc,
        IReadOnlyCollection<JournalLineInput> lines)
    {
        EnsureBalanced(lines);

        var entry = new JournalEntry
        {
            EntryDateUtc = nowUtc,
            DescriptionAr = descriptionAr,
            DescriptionEn = descriptionEn,
            SourceType = sourceType,
            SourceId = sourceId,
            UnitId = unitId,
            CreatedByUserId = createdByUserId
        };
        foreach (var line in lines)
            entry._lines.Add(JournalLine.Create(line.AccountId, line.Debit, line.Credit, line.Memo));
        return entry;
    }

    /// <summary>A new entry with the same lines, debit and credit swapped; this one is marked reversed.</summary>
    public JournalEntry Reverse(string descriptionAr, string descriptionEn, Guid createdByUserId, DateTime nowUtc)
    {
        if (IsReversed || ReversalOfId is not null)
            throw new InvalidOperationException("Only an active original entry can be reversed.");

        var reversal = Create(
            SourceType, SourceId, UnitId, descriptionAr, descriptionEn, createdByUserId, nowUtc,
            _lines.Select(l => new JournalLineInput(l.AccountId, l.Credit, l.Debit, l.Memo)).ToList());
        reversal.ReversalOfId = Id;
        IsReversed = true;
        return reversal;
    }

    private static void EnsureBalanced(IReadOnlyCollection<JournalLineInput> lines)
    {
        if (lines.Count < 2)
            throw new InvalidOperationException("A journal entry needs at least two lines.");
        if (lines.Any(l => l.Debit < 0 || l.Credit < 0 || (l.Debit > 0) == (l.Credit > 0)))
            throw new InvalidOperationException("Each line is either a positive debit or a positive credit.");
        if (lines.Sum(l => l.Debit) != lines.Sum(l => l.Credit))
            throw new InvalidOperationException("Total debit must equal total credit.");
    }
}

public sealed record JournalLineInput(int AccountId, decimal Debit, decimal Credit, string? Memo = null);
